function BelowZero(operations: array of integer): boolean;
begin
  var balance := 0;
  foreach var op in operations do
  begin
    balance += op;
    if balance < 0 then
    begin
      Result := True;
      exit;
    end;
  end;
  Result := False;
end;


function MeanAbsoluteDeviation(numbers: array of real): real;
