function HowManyTimes(str: string; substring: string): integer;
begin
  var count := 0;
  var i := 1;
  while i <= str.Length do
  begin
    var found := True;
    for var j := 1 to substring.Length do
      if str[i + j - 1] <> substring[j] then
      begin
        found := False;
        break;
      end;
    if found then
      count += 1;
    i += substring.Length;
  end;
  Result := count;
end;


