function SortThird(l: array of integer): array of integer;
begin
  var third := new List<integer>;
  var others := new List<integer>;
  var div3 := new List<integer>;

  for var i := 0 to l.Length - 1 do
  begin
    if i mod 3 = 0 then
      div3.Add(l[i])
    else
      others.Add(l[i]);
  end;

  div3.Sort;

  for var i := 0 to l.Length - 1 do
  begin
    if i mod 3 = 0 then
      l[i] := div3[i]
    else
      l[i] := others[i];
  end;

  Result := l;
end;


