function ChangeBase(x: integer; base: integer): string;
begin
  if x = 0 then
  begin
    Result := '0';
    exit;
  end;

  var s := '';
  var num := x;

  while num > 0 do
  begin
    var digit := num mod base;
    s := Chr(digit + Ord('0')) + s;
    num := num div base;
  end;

  Result := s;
end;


