function CorrectBracketing(brackets: string): boolean;
begin
  var stack := new Stack<char>;
  foreach var ch in brackets do
  begin
    if ch = '<' then
      stack.Push(ch)
    else if (ch = '>') and (stack.Count > 0) then
      stack.Pop
    else
    begin
      Result := False;
      exit;
    end;
  end;
  Result := stack.Count = 0;
end;


function Monotonic(l: array of integer): boolean;
begin
  if l.Length = 0 then
  begin
    Result := True;
    exit;
  end;

  var isIncreasing := True;
  var isDecreasing := True;

  for var i := 1 to l.Length - 1 do
  begin
    if l[i] > l[i - 1] then
      isDecreasing := False
    else if l[i] < l[i - 1] then
      isIncreasing := False;
  end;

  Result := isIncreasing or isDecreasing;
end;


function Common(l1, l2: array of integer): array of integer;
begin
  var set1 := new HashSet<integer>(l1);
  var set2 := new HashSet<integer>(l2);
  var common := new List<integer>;

  foreach var i in set1 do
    if set2.Contains(i) then
      common.Add(i);

  Result := common.ToArray;
end;


function LargestPrimeFactor(n: integer): integer;
begin
  var i := 2;
  while i * i <= n do
  begin
    if n mod i = 0 then
    begin
      n := n div i;
      i := 2;
    end
    else
      i += 1;
  end;
  Result := n;
end;


function SumToN(n: integer): integer;
begin
  var sum := 0;
  for var i := 1 to n do
    sum += i;
  Result := sum;
end;


function CorrectBracketing(brackets: string): boolean;
begin
  var stack := new Stack<char>;
  foreach var ch in brackets do
  begin
    if ch = '(' then
      stack.Push(ch)
    else if (ch = ')') and (stack.Count > 0) then
      stack.Pop
    else
    begin
      Result := False;
      exit;
    end;
  end;
  Result := stack.Count = 0;
end;


function Derivative(xs: array of real): array of real;
begin
  var n := xs.Length;
  if n = 0 then
    Result := new real[0]
  else if n = 1 then
    Result := new real[0]
  else
  begin
    var res := new real[n - 1];
    for var i := 1 to n - 1 do
      res[i - 1] := i * xs[i];
    Result := res;
  end;
end;


function Fibfib(n: integer): integer;
begin
  if n = 0 then
    Result := 0
  else if n = 1 then
    Result := 0
  else if n = 2 then
    Result := 1
  else
  begin
    var fibfibList := new List<integer>;
    fibfibList.Add(0);
    fibfibList.Add(0);
    fibfibList.Add(1);

    for var i := 3 to n do
      fibfibList.Add(fibfibList[i-1] + fibfibList[i-2] + fibfibList[i-3]);

    Result := fibfibList[n];
  end;
end;


function VowelsCount(s: string): integer;
begin
  var vowels := new HashSet<char>('aeiou'.ToCharArray);
  var count := 0;
  var lastChar := ' ';

  for var i := 1 to s.Length do
  begin
    var ch := s[i];
    if (vowels.Contains(ch)) and (ch <> 'y') and (ch <> 'Y') then
      count += 1;

    if (ch = 'y') or (ch = 'Y') then
    begin
      if (i = s.Length) or (lastChar = 'y') or (lastChar = 'Y') then
        count += 1;
    end;

    lastChar := ch;
  end;

  Result := count;
end;


function CircularShift(x: integer; shift: integer): string;
begin
  var digits := x.ToString.ToCharArray;
  var n := digits.Length;
  shift := shift mod n;
  var shifted := new char[n];
  for var i := 0 to n - 1 do
    shifted[(i + shift) mod n] := digits[i];
  Result := new string(shifted);
end;


function Digitsum(s: string): integer;
begin
  var sum := 0;
  foreach var ch in s do
    if (ch >= 'A') and (ch <= 'Z') then
      sum += Ord(ch) - Ord('A') + 1;
  Result := sum;
end;


function FruitDistribution(s: string; n: integer): integer;
begin
  var parts := s.Split(' and ');
  var apples := parts[0].Split(' ');
  var oranges := parts[1].Split(' ');
  var totalApples := StrToInt(apples[0]);
  var totalOranges := StrToInt(oranges[0]);
  var totalFruits := totalApples + totalOranges;
  var mangoFruits := n - totalFruits;
  Result := mangoFruits;
end;


function Pluck(arr: array of integer): array of integer;
begin
  var smallestEven := integer.MaxValue;
  var smallestIndex := -1;
  var smallestValue := -1;

  for var i := 0 to arr.Length - 1 do
  begin
    if (arr[i] mod 2 = 0) and (arr[i] < smallestEven) then
    begin
      smallestEven := arr[i];
      smallestIndex := i;
      smallestValue := arr[i];
    end;
  end;

  if smallestIndex = -1 then
    Result := new integer[0]
  else
    Result := |smallestValue, smallestIndex|;
end;


function Search(lst: array of integer): integer;
begin
  var freq := new Dictionary<integer, integer>;
  foreach var i in lst do
    if freq.ContainsKey(i) then
      freq[i] += 1
    else
      freq[i] := 1;
  var maxVal := -1;
  var maxFreq := -1;
  foreach var kv in freq do
  begin
    if (kv.Value > maxFreq) and (kv.Key > maxVal) then
    begin
      maxVal := kv.Key;
      maxFreq := kv.Value;
    end;
  end;
  Result := maxVal;
end;


function StrangeSortList(lst: array of integer): array of integer;
begin
  if lst.Length = 0 then
  begin
    Result := new integer[0];
    exit;
  end;

  var sorted := lst.ToArray;
  var n := sorted.Length;
  var res := new integer[n];
  var i := 0;

  while n > 0 do
  begin
    if n mod 2 = 1 then
      res[i] := sorted[n - 1]
    else
      res[i] := sorted[n - 2];
    i += 1;
    n -= 1;
  end;

  Result := res;
end;


function TriangleArea(a, b, c: real): real;
begin
  if (a + b > c) and (a + c > b) and (b + c > a) then
  begin
    var s := (a + b + c) / 2;
    var area := Sqrt(s * (s - a) * (s - b) * (s - c));
    Result := Round(area, 2);
  end
  else
    Result := -1;
end;


function WillItFly(q: array of integer; w: integer): boolean;
begin
  var isBalanced := True;
  var sum := 0;

  for var i := 0 to q.Length - 1 do
  begin
    sum += q[i];
    if q[i] <> q[q.Length - 1 - i] then
    begin
      isBalanced := False;
      break;
    end;
  end;

  Result := isBalanced and (sum <= w);
end;


function SmallestChange(arr: array of integer): integer;
begin
  var n := arr.Length;
  var dp := new integer[n + 1, n + 1];

  for var i := n - 1 downto 0 do
  begin
    for var j := n - 1 downto 0 do
    begin
      if arr[i] = arr[j] then
        dp[i, j] := dp[i + 1, j + 1]
      else
        dp[i, j] := Min(dp[i + 1, j], dp[i, j + 1]) + 1;
    end;
  end;

  Result := dp[0, 0];
end;


