end;


function IsMultiplyPrime(a: integer): boolean;
begin
  var primes := new List<integer>;
  var n := a;
  var i := 2;
  while n > 1 do
  begin
    if n.IsPrime then
    begin
      primes.Add(i);
      n := n div i;
    end
    else
      i += 1;
  end;
  var primeCount := primes.Count;
  if primeCount = 3 then
  begin
    var product := 1;
    foreach var p in primes do
      product *= p;
    Result := product = a;
  end
  else
    Result := false;
end;


function IsSimplePower(x, n: integer): boolean;
begin
  Result := n.Power(Round(Log(x) / Log(n))) = x;
end;


function Iscube(a: integer): boolean;
begin
  var root := Round(Sqrt(a));
  Result := a = root * root * root;
end;


