  var count := 0;
  foreach var ch in num do
    if hexToDec.ContainsKey(ch) then
      count += 1;
  Result := count;
end;


function DecimalToBinary(decimal: integer): string;
begin
  var binary := '';
  var num := decimal;

  while num > 0 do
  begin
    binary := (num mod 2) + binary;
    num := num div 2;
  end;

  Result := 'db' + binary + 'db';
end;


