function Solve(n: integer): string;
begin
  var sum := 0;
  var N := n;
  while N > 0 do
  begin
    sum += N mod 10;
    N := N div 10;
  end;
  Result := sum.ToString;
end;


function Add(lst: array of integer): integer;
begin
  var sum := 0;
  for var i := 0 to lst.Length - 1 step 2 do
    sum += lst[i];
