function AntiShuffle(s: string): string;
begin
  var words := s.Split(' ');
  var sortedWords := words.Select(w -> w.ToCharArray.Order.Select(c -> c.ToString).JoinToString).ToArray;
  Result := sortedWords.JoinToString;
end;


function GetRow(lst: array of array of integer; x: integer): array of (integer, integer);
begin
  var res := new List<(integer, integer)>;
  for var i := 0 to lst.Length - 1 do
    for var j := 0 to lst[i].Length - 1 do
      if lst[i][j] = x then
        res.Add((i, j));
  res.Sort((a, b) ->
  begin
    if a.Item1 < b.Item1 then
      Result := -1
    else if a.Item1 = b.Item1 then
    begin
      if a.Item2 < b.Item2 then
        Result := -1
      else if a.Item2 = b.Item2 then
        Result := 0
      else
        Result := 1;
    end
    else
      Result := 1;
  end);
  Result := res.ToArray;
end;


function SortArray(arr: array of integer): array of integer;
begin
  if arr.Length = 0 then
  begin
    Result := new integer[0];
    exit;
  end;

  var sorted := arr.ToArray;
  var sum := sorted[0] + sorted[sorted.Length - 1];

  if (sum mod 2) = 0 then
    sorted := sorted.OrderDescending.ToArray
  else
    sorted := sorted.Order.ToArray;

  Result := sorted;
end;


function Encrypt(s: string): string;
begin
  var encrypted := '';
  foreach var ch in s do
  begin
    if ch.IsLower then
      encrypted := encrypted + Chr((Ord(ch) - Ord('a') + 2) mod 26 + Ord('a'))
    else
      encrypted := encrypted + Chr((Ord(ch) - Ord('A') + 2) mod 26 + Ord('A'));
  end;
  Result := encrypted;
end;


function NextSmallest(lst: array of integer): integer;
begin
  var uniqueLst := lst.Distinct.ToArray;
  if uniqueLst.Length < 2 then
    Result := integer.MaxValue
  else
  begin
    &Array.Sort(uniqueLst);
    Result := uniqueLst[1];
  end;
end;


function IsBored(s: string): integer;
begin
  var sentences := s.Split(new string[] {'.', '?', '!'}, StringSplitOptions.RemoveEmptyEntries);
  var boredomCount := 0;

  foreach var sentence in sentences do
  begin
    var words := sentence.Split(' ');
    if (words.Length > 0) and (words[0] = 'I') then
      boredomCount += 1;
  end;

  Result := boredomCount;
end;


function AnyInt(x, y, z: real): boolean;
begin
  Result := (x = y + z) or (y = x + z) or (z = x + y);
end;


function Encode(message: string): string;
begin
  var vowels := new Dictionary<char, char>;
  var alphabet := 'abcdefghijklmnopqrstuvwxyz';
  var shifted := alphabet.Substring(2) + alphabet.Substring(0, 2);
  for var i := 1 to alphabet.Length do
    vowels[alphabet[i]] := shifted[i];

  var sb := new StringBuilder;
  foreach var ch in message do
  begin
    if ch.IsLetter then
    begin
      if vowels.ContainsKey(ch) then
        sb.Append(vowels[ch])
      else
        sb.Append(ch);
    end
    else
      sb.Append(ch);
  end;
  Result := sb.ToString;
end;


function Skjkasdkd(lst: array of integer): integer;
begin
  var maxPrime := -1;
  foreach var i in lst do
  begin
    if (i > 1) and (i mod 2 <> 0) then
    begin
      var isPrime := True;
      var sqrt := i.Sqrt;
      for var j := 3 to Round(sqrt) step 2 do
        if i mod j = 0 then
        begin
          isPrime := False;
          break;
        end;
      if isPrime then
        if i > maxPrime then
          maxPrime := i;
    end;
  end;
  if maxPrime = -1 then
    Result := 0
  else
  begin
    var sumOfDigits := 0;
    while maxPrime > 0 do
    begin
      sumOfDigits += maxPrime mod 10;
      maxPrime := maxPrime div 10;
    end;
    Result := sumOfDigits;
  end;
end;


function CheckDictCase(dict: Dictionary<string, string>): boolean;
begin
  if dict.Count = 0 then
  begin
    Result := True;
    exit;
  end;

  var lowerKeys := new List<string>;
  var upperKeys := new List<string>;

  foreach var kv in dict do
  begin
    var key := kv.Key.ToLower;
    if key = kv.Key then
      lowerKeys.Add(key)
    else
      upperKeys.Add(key);
  end;

  Result := (lowerKeys.Count = dict.Count) or (upperKeys.Count = dict.Count);
end;


function CountUpTo(n: integer): array of integer;
begin
  var primes := new List<integer>;
  for var i := 2 to n - 1 do
  begin
    var isPrime := True;
    for var j := 2 to i - 1 do
      if i mod j = 0 then
      begin
        isPrime := False;
        break;
      end;
    if isPrime then
      primes.Add(i);
  end;
  Result := primes.ToArray;
end;


function Multiply(a, b: integer): integer;
begin
  var product := 0;
  var aStr := a.ToString;
  var bStr := b.ToString;
  for var i := 1 to aStr.Length do
  begin
    var digit := StrToInt(aStr[i].ToString);
    for var j := 1 to bStr.Length do
    begin
      var digit2 := StrToInt(bStr[j].ToString);
      product += digit * digit2;
    end;
  end;
  Result := product;
end;


function CountUpper(s: string): integer;
begin
  var count := 0;
  var vowels := new HashSet<char>('aeiouAEIOU'.ToCharArray);

  for var i := 1 to s.Length do
    if (i mod 2 = 0) and (vowels.Contains(s[i])) then
      count += 1;

  Result := count;
end;


function ClosestInteger(value: string): integer;
begin
  var parts := value.Split('.');
  var num := parts[0];
  var decimals := parts.Length = 2 ? parts[1] : '';
  var numVal := StrToInt(num);
  var decVal := StrToInt(decimals);
  var diff := numVal - (numVal div 10 * 10);
  if (diff = 5) or (diff = -5) then
    Result := numVal + (10 - (numVal div 10 * 10))
  else if (diff = 4) or (diff = -4) then
    Result := numVal - (10 - (numVal div 10 * 10))
  else
    Result := numVal;
end;


function MakeAPile(n: integer): array of integer;
begin
  var stones := new List<integer>;
  var stone := 1;
  for var i := 0 to n - 1 do
  begin
    stones.Add(stone);
    if n mod 2 = 0 then
      stone += 2
    else
      stone += 1;
  end;
  Result := stones.ToArray;
end;


function WordsString(s: string): array of string;
begin
  var parts := s.Split(',', ' ');
  Result := parts;
end;


function ChooseNum(x, y: integer): integer;
begin
  var maxNum := -1;
  for var i := y downto x do
    if (i mod 2 = 0) and (i >= x) then
      if (maxNum = -1) or (i > maxNum) then
        maxNum := i;
  Result := maxNum;
end;


function RoundedAvg(n, m: integer): string;
begin
  if n > m then
  begin
    Result := '-1';
    exit;
  end;

  var total := 0;
  for var i := n to m do
    total += i;

  var avg := total / (m - n + 1);
  var rounded := Round(avg);

  Result := '0b' + Convert.ToString(rounded, 2);
end;


function UniqueDigits(x: array of integer): array of integer;
begin
  var unique := new List<integer>;
  var digits := new List<integer>;

  foreach var num in x do
  begin
    var numStr := num.ToString;
    foreach var ch in numStr do
      digits.Add(StrToInt(ch));
  end;

  var uniqueDigits := digits.Distinct.ToList;

  foreach var num in x do
  begin
    var hasEven := false;
    var numStr := num.ToString;

    foreach var ch in numStr do
      if StrToInt(ch) in uniqueDigits then
        hasEven := true;

    if not hasEven then
      unique.Add(num);
  end;

  Result := unique.Order.ToArray;
end;


function ByLength(arr: array of integer): array of string;
begin
  var res := new List<string>;
  var temp := new List<integer>;

  foreach var i in arr do
    if (i >= 1) and (i <= 9) then
      temp.Add(i);

  temp.Sort;
  temp.Reverse;

  var name := new List<string>(|'One', 'Two', 'Three', 'Four', 'Five', 'Six', 'Seven', 'Eight', 'Nine'|);

  for var i := 0 to temp.Count - 1 do
    res.Add(name[temp[i] - 1]);

  Result := res.ToArray;
end;


function F(n: integer): array of integer;
begin
  var res := new List<integer>;
  for var i := 1 to n do
  begin
    if i mod 2 = 0 then
      res.Add(Factorial(i))
    else
      res.Add(i + (1..i).Sum);
  end;
  Result := res.ToArray;
end;


function EvenOddPalindrome(n: integer): (integer, integer);
begin
  var evenCount := 0;
  var oddCount := 0;
  for var i := 1 to n do
  begin
    var numStr := i.ToString;
    var isPalindrome := True;
    for var j := 1 to numStr.Length do
      if numStr[j] <> numStr[numStr.Length - j + 1] then
      begin
        isPalindrome := False;
        break;
      end;
    if isPalindrome then
      if i mod 2 = 0 then
        evenCount += 1
      else
        oddCount += 1;
  end;
  Result := (evenCount, oddCount);
end;


function CountNums(arr: array of integer): integer;
begin
  var count := 0;
  foreach var num in arr do
  begin
    var sum := 0;
    var numStr := Abs(num).ToString;
    for var i := 1 to numStr.Length do
      sum += StrToInt(numStr[i]);
    if sum > 0 then
      count += 1;
  end;
  Result := count;
end;


function MoveOneBall(arr: array of integer): boolean;
begin
  if arr.Length = 0 then
  begin
    Result := True;
    exit;
  end;

  var sorted := arr.ToArray;
  var n := sorted.Length;

  for var i := 0 to n - 1 do
  begin
    var j := i;
    while (j > 0) and (sorted[j] < sorted[j - 1]) do
    begin
      var temp := sorted[j];
      sorted[j] := sorted[j - 1];
      sorted[j - 1] := temp;
      j -= 1;
    end;
  end;

  for var i := 0 to n - 1 do
    if sorted[i] <> sorted[i + 1] then
    begin
      Result := False;
      exit;
    end;

  Result := True;
end;


function Exchange(lst1, lst2: array of integer): string;
begin
  var evenCount1 := 0;
