  var histogram := new Dictionary<string, integer>;
  var maxCount := 0;
  var maxLetters := new List<string>;

  foreach var word in words do
  begin
    if not histogram.ContainsKey(word) then
      histogram[word] := 0;

    histogram[word] := histogram[word] + 1;

    if histogram[word] > maxCount then
    begin
      maxCount := histogram[word];
      maxLetters.Clear;
      maxLetters.Add(word);
    end
    else if histogram[word] = maxCount then
      maxLetters.Add(word);
  end;

  Result := new Dictionary<string, integer>;
  foreach var letter in maxLetters do
    Result[letter] := maxCount;
end;


