function MaxFill(grid: array of array of integer; capacity: integer): integer;
begin
  var m := grid.Length;
  var n := grid[0].Length;
  var buckets := new integer[m, n];
  var res := 0;

  for var i := 0 to m - 1 do
    for var j := 0 to n - 1 do
      if grid[i, j] = 1 then
        buckets[i, j] := capacity;

  for var i := 0 to m - 1 do
    for var j := 0 to n - 1 do
      if buckets[i, j] > 0 then
      begin
        var cnt := 0;
        var x := i;
        while (x >= 0) and (buckets[x, j] > 0) do
        begin
          buckets[x, j] := buckets[x, j] - 1;
          cnt := cnt + 1;
          x := x - 1;
        end;
        res := res + cnt;
      end;

  Result := res;
end;


