function Minpath(grid: array of array of integer; k: integer): array of integer;
begin
  var n := grid.Length;
  var directions := new List<(integer, integer)>;
  directions.Add((-1, 0));
  directions.Add((1, 0));
  directions.Add((0, -1));
  directions.Add((0, 1));

  var visited := new HashSet<(integer, integer)>;
  var queue := new Queue<(integer, integer, integer)>;
  queue.Enqueue((0, 0, 0));
  var res := new List<integer>;

  while queue.Count > 0 do
  begin
    var (x, y, steps) := queue.Dequeue;

    if steps = k then
    begin
      res.Add(grid[x, y]);
      continue;
    end;

    for var i := 0 to 3 do
    begin
      var nx := x + directions[i].Item1;
      var ny := y + directions[i].Item2;

      if (nx >= 0) and (nx < n) and (ny >= 0) and (ny < n) and 
         not visited.Contains((nx, ny)) then
      begin
        visited.Add((nx, ny));
        queue.Enqueue((nx, ny, steps + 1));
      end;
    end;
  end;

  Result := res.ToArray;
end;


