function StrongestExtension(className: string; extensions: array of string): string;
begin
  var maxStrength := -1.0;
  var strongestExtension := '';

  foreach var extension in extensions do
  begin
    var cap := 0;
    var sm := 0;

    for var i := 1 to extension.Length do
    begin
      if Char.IsUpper(extension[i]) then
        cap += 1;
      if Char.IsLower(extension[i]) then
        sm += 1;
    end;

    var strength := cap - sm;

    if strength > maxStrength then
    begin
      maxStrength := strength;
      strongestExtension := extension;
    end;
  end;

  Result := className + '.' + strongestExtension;
end;


function CycpatternCheck(a, b: string): boolean;
begin
  var rotations := new List<string>;
  for var i := 0 to b.Length - 1 do
    rotations.Add(b.Substring(i) + b.Substring(0, i));
  foreach var r in rotations do
    if a.Contains(r) then
    begin
      Result := True;
      exit;
    end;
  Result := False;
end;


function EvenOddCount(num: integer): (integer, integer);
begin
  var evenCount := 0;
  var oddCount := 0;
  var n := Abs(num);

  while n > 0 do
  begin
    var digit := n mod 10;
    if digit mod 2 = 0 then
      evenCount += 1
    else
      oddCount += 1;
    n := n div 10;
  end;

  Result := (evenCount, oddCount);
end;


function IntToMiniRoman(number: integer): string;
begin
  var roman := '';
  var values := new Dictionary<integer, string>;
  values.Add(1000, 'm');
  values.Add(900, 'cm');
  values.Add(500, 'd');
  values.Add(400, 'cd');
  values.Add(100, 'c');
  values.Add(90, 'xc');
  values.Add(50, 'l');
  values.Add(40, 'xl');
  values.Add(10, 'x');
  values.Add(9, 'ix');
  values.Add(5, 'v');
  values.Add(4, 'iv');
  values.Add(1, 'i');

  foreach var kv in values do
  begin
    while number >= kv.Key do
    begin
      roman += kv.Value;
      number -= kv.Key;
    end;
  end;

  Result := roman.ToLower;
end;


function RightAngleTriangle(a, b, c: integer): boolean;
begin
  if (a + b > c) and (a + c > b) and (b + c > a) then
    Result := True
  else
    Result := False;
end;


function FindMax(words: array of string): string;
begin
  var maxUnique := 0;
  var maxWord := '';

  foreach var word in words do
  begin
    var uniqueChars := new HashSet<char>(word);
    if uniqueChars.Count > maxUnique then
    begin
      maxUnique := uniqueChars.Count;
      maxWord := word;
    end;
  end;

  Result := maxWord;
end;


function Eat(number, need, remaining: integer): (integer, integer);
begin
  var eaten := number;
  var left := remaining;

  if (need <= left) and (number < need) then
    eaten := number + left;

  Result := (eaten, eaten - number);
end;


function DoAlgebra(op: array of string; operand: array of integer): integer;
begin
  var res := operand[0];
  for var i := 1 to operand.Length - 1 do
  begin
    case op[i-1] of
      '+': res := res + operand[i];
      '-': res := res - operand[i];
      '*': res := res * operand[i];
      '//': res := res div operand[i];
      '**': res := Round(Power(res, operand[i]));
    end;
  end;
  Result := res;
end;


function Solve(s: string): string;
begin
  var sb := new StringBuilder;
  foreach var ch in s do
  begin
    if Char.IsLetter(ch) then
    begin
      if Char.IsLower(ch) then
        sb.Append(Char.ToUpper(ch))
      else
        sb.Append(Char.ToLower(ch));
    end
    else
      sb.Append(ch);
  end;
  Result := sb.ToString;
end;


function StringToMd5(text: string): string;
begin
  if text = '' then
  begin
    Result := nil;
    exit;
  end;

  var md5 := new System.Security.Cryptography.MD5CryptoServiceProvider;
  var bytes := Encoding.UTF8.GetBytes(text);
  var hash := md5.ComputeHash(bytes);
  var sb := new System.Text.StringBuilder;

  foreach var b in hash do
    sb.Append(b.ToString('x2'));

  Result := sb.ToString;
end;


function GenerateIntegers(a, b: integer): array of integer;
begin
  var res := new List<integer>;
  for var i := a to b do
    if i mod 2 = 0 then
      res.Add(i);
  Result := res.ToArray;
end;
